INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62142215', 62142215, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'SUKU DINAS CIPTA KARYA, TATA RUANG DAN PERTANAHAN KOTA ADMINISTRASI  JAKARTA PUSAT', 'Penyusunan Dokumen Teknis Gedung Pemda - SAPS 13 (Struktur) 2026', 'Jasa Lainnya', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 82582500, 'December 2025', 'APBD', 1, 1, '1 Paket', '"Lingkup kegiatan yang dilakukan oleh penyedia jasa Senior Assistant Professional Staff (SAPS) 13 - Struktur, meliputi: a. Membantu memeriksa dan meneliti Berita Acara Bobot Kemajuan Pekerjaan yang diajukan oleh penyedia jasa pemborongan fisik/kontraktor untuk pembayaran termin apabila kuantitas dan kualitas pekerjaan sudah memenuhi; b. Membantu memeriksa pelaksanaan pembangunan fisik sesuai dengan ketentuan yang berlaku; c. Membantu memeriksa dan mengkaji kembali (review) kesesuaian volume pekerjaan antara gambar kerja dengan Rencana Anggaran Biaya (RAB) terutama di awal pelaksanaan pekerjaan fisik dan menyampaikan usulan penyempurnaan bila didapati ketidaksesuaian; d. Membantu tugas-tugas Pejabat Pembuat Komitmen dalam menjamin pekerjaan konstruksi/fisik gedung sesuai dengan dokumen kontrak, kecuali jika disepakati dan mendapat persetujuan untuk dilakukannya perubahan; e. Membantu mengawasi pelaksanaan yang dilaksanakan oleh Kontraktor dari segi kualitas, kuantitas dan laju pencapaian prestasi pekerjaan; dan f. Melaporkan dan memberikan saran atas hasil pekerjaan yang tidak memenuhi persyaratan "', '"Senior Assistant Profesional Staff bidang Struktur dengan ketentuan sebagai berikut : a. Pendidikan Minimal S1/D4/Setara Jurusan Teknik Sipil dari Universitas Negeri/ Swasta dengan status lain yang telah mengikuti ujian negara atau lulusan luar negeri bagi penyedia jasa Senior Assistant Professional Staff; b. Memiliki kompetensi sesuai bidang yang dipersyaratkan yang dibuktikan dengan ijazah dan transkrip nilai pendidikan terakhir Jurusan Teknik Sipil sertifikat keahlian/teknis seperti aplikasi AutoCAD, SAP 2000/Etabs, Microsoft Office dan/atau sertifikat pelatihan/kursus; dan c. Pengalaman Kerja minimal 1 tahun di bidang perencanaan, pembangunan, perawatan bangunan gedung dan/atau pekerjaan sejenis. "', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 238216);
